#include <cstdio>
#include <typeinfo>

int main() {
    int int_value = 0;
    double double_value = 0.0;
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < 1 || n > 20) return 1;
    for (int i = 0; i < n; i++) {
        char first[8];
        char second[8];
        if (std::scanf("%7s %7s", first, second) != 2) return 1;
        if ((first[0] != 'i' && first[0] != 'd') || first[1] != '\0') return 1;
        if ((second[0] != 'i' && second[0] != 'd') || second[1] != '\0') return 1;
        int* first_as_int = first[0] == 'i' ? &int_value : nullptr;
        double* first_as_double = first[0] == 'd' ? &double_value : nullptr;
        int* second_as_int = second[0] == 'i' ? &int_value : nullptr;
        double* second_as_double = second[0] == 'd' ? &double_value : nullptr;
        bool same = false;
        if (first_as_int != nullptr) {
            same = second_as_int != nullptr && typeid(*first_as_int) == typeid(*second_as_int);
        } else {
            same = second_as_double != nullptr && typeid(*first_as_double) == typeid(*second_as_double);
        }
        std::printf("%s\n", same ? "same" : "diff");
    }
    return 0;
}
